// IssueInvite is CreateInvite that also returns the invite's token, which only the invitation email carries.
// It revokes the address's older pending invites to the organization, so that only the newest token works.
func (s *Store) IssueInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, string, error) {
	email = strings.TrimSpace(email)
	if !validEmail(email) {
		return Invite{}, "", invalid("an invite needs a valid email address")
	}
	if !role.Valid() || role == RoleOwner {
		return Invite{}, "", invalid("an invite's role is admin, billing, member or viewer")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return Invite{}, "", ErrNotFound
	}
	if uid, ok := s.usersByEmail[normEmail(email)]; ok {
		if _, member := s.members[memberKey{orgID, uid}]; member {
			return Invite{}, "", ErrAlreadyMember
		}
	}
	for id, old := range s.invites {
		if old.OrgID == orgID && normEmail(old.Email) == normEmail(email) && old.AcceptedAt == nil && old.RevokedAt == nil {
			t := now.UTC()
			old.RevokedAt = &t
			s.invites[id] = old
		}
	}
	token := newInviteToken()
	inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, TokenHash: hashToken(token), InvitedBy: invitedBy, CreatedAt: now.UTC()}
	s.invites[inv.ID] = inv
	return inv, token, nil
}

