180	// acceptInvite needs no API key: the invite's token is the credential. It answers the new member and their first API key.
181	func (s *Server) acceptInvite(w http.ResponseWriter, r *http.Request) {
182		var in struct {
183			Token string `json:"token"`
184			Name  string `json:"name"`
185		}
186		if !decode(w, r, &in) {
187			return
188		}
189		u, m, k, err := s.store.AcceptInvite(in.Token, in.Name, s.clock.Now())
190		if err != nil {
191			if errors.Is(err, store.ErrNotFound) {
192				writeError(w, http.StatusNotFound, "invite_not_found", "no such invite")
193				return
194			}
195			if errors.Is(err, store.ErrInviteUsed) {
196				writeError(w, http.StatusGone, "invite_used", "this invite was already accepted")
197				return
198			}
199			if errors.Is(err, store.ErrInviteExpired) {
200				writeError(w, http.StatusGone, "invite_expired", "this invite has expired")
201				return
202			}
203			s.storeError(w, err)
204			return
205		}
206		writeJSON(w, http.StatusCreated, map[string]any{"user": u, "member": s.memberView(m), "api_key": k})
207	}
